# Surah Hud (chapter 11) — part 10: ayat 91-100 (IDs 1564-1573)
SURAH = 11

ENTRIES = {
1564: (
"انہوں نے — کہا — اے — شعیبؑ — ہم — تمہاری — اکثر — باتیں — نہیں سمجھتے — اور — بے شک — ہم — تم — کو — ہمارے درمیان — کمزور — دیکھتے ہیں — اور — اگر — تمہارا — خاندان — نہ ہوتا — تو — ہم — تجھے — رجم — کر دیتے — اور — تم — ہم پر — عزیز — نہیں",
"""۱۔ مدین والے — شعیبؑ کو — کمزور — اور — غیر محفوظ سمجھتے ہیں۔
۲۔ ’’قَالُوا يَا شُعَيْبُ مَا نَفْقَهُ كَثِيرًا مِّمَّا تَقُولُ وَإِنَّا لَنَرَاكَ فِينَا ضَعِيفًا وَلَوْلَا رَهْطُكَ لَرَجَمْنَاكَ وَمَا أَنتَ عَلَيْنَا بِعَزِيزٍ‘‘ — انہوں نے — کہا — اے — شعیبؑ — ہم — تمہاری — اکثر — باتیں — نہیں سمجھتے — اور — بے شک — ہم — تم — کو — ہمارے درمیان — کمزور — دیکھتے ہیں — اور — اگر — تمہارا — خاندان — نہ ہوتا — تو — ہم — تجھے — رجم — کر دیتے — اور — تم — ہم پر — عزیز — نہیں — یعنی انہوں نے کہا — اے شعیبؑ — ہم تمہاری — اکثر — باتیں — نہیں — سمجھتے — اور ہم تمہیں — ہمارے درمیان — کمزور — دیکھتے ہیں — اور اگر تمہارا — خاندان — نہ ہوتا — تو — ہم — تجھے — رجم — کر دیتے — اور تم — ہم پر — عزیز — نہیں۔
۳۔ عملی سبق: حق — کمزوری — میں — بھی — حق — ہوتا ہے؛ طاقت — نجات کی شرط — نہیں۔"""
),
1565: (
"انہوں نے — کہا — اے — میری قوم — کیا — میرا خاندان — تم — پر اللہ — سے — زیادہ — عزیز — ہے — اور — تم — نے — اسے — اپنے پیچھے — پھینک — دیا — بے شک — میرا رب — تم — کے — اعمال — پر — حاوی — ہے",
"""۱۔ شعیبؑ — خاندان کی — اور — اللہ کی — نسبت — واضح کرتے ہیں۔
۲۔ ’’قَالَ يَا قَوْمِ أَرَهْطِي أَعَزُّ عَلَيْكُم مِّنَ اللَّهِ وَاتَّخَذْتُمُوهُ وَرَاءَكُمْ ظِهْرِيًّا إِنَّ رَبِّي بِمَا تَعْمَلُونَ مُحِيطٌ‘‘ — انہوں نے — کہا — اے — میری قوم — کیا — میرا خاندان — تم — پر اللہ — سے — زیادہ — عزیز — ہے — اور — تم — نے — اسے — اپنے پیچھے — پھینک — دیا — بے شک — میرا رب — تم — کے — اعمال — پر — حاوی — ہے — یعنی شعیبؑ — نے کہا — اے — میری قوم — کیا میرا خاندان — تم — پر — اللہ سے زیادہ — عزیز ہے — اور — تم — نے — اسے — اپنے پیچھے — پھینک — دیا — بے شک — میرا رب — تمہارے — اعمال — پر — حاوی — ہے۔
۳۔ عملی سبق: اللہ سے بڑھ کر — کسی — کی پرستش — نہیں کرنی چاہیے۔"""
),
1566: (
"اور — اے میری قوم — اپنی جگہ — پر — عمل کرو — بے شک — میں بھی عمل — کر رہا ہوں — عنقریب — تم — جانو گے — کس پر — ایسا عذاب — آتا ہے — جو — اسے — رسوا — کر دے — اور — کون — جھوٹا — ہے — اور — انتظار کرو — بے شک — میں — بھی تمہارے ساتھ — انتظار — کرنے والا — ہوں",
"""۱۔ شعیبؑ — قوم کو فیصلہ کن — ہلاکت — کا پیغام دیتے ہیں۔
۲۔ ’’وَيَا قَوْمِ اعْمَلُوا عَلَىٰ مَكَانَتِكُمْ إِنِّي عَامِلٌ سَوْفَ تَعْلَمُونَ مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَمَن هُوَ كَاذِبٌ وَارْتَقِبُوا إِنِّي مَعَكُمْ رَقِيبٌ‘‘ — اور — اے میری قوم — اپنی جگہ — پر — عمل کرو — بے شک — میں بھی عمل — کر رہا ہوں — عنقریب — تم — جانو گے — کس پر — ایسا عذاب — آتا ہے — جو — اسے — رسوا — کر دے — اور — کون — جھوٹا — ہے — اور — انتظار کرو — بے شک — میں — بھی تمہارے ساتھ — انتظار — کرنے والا — ہوں — یعنی اے میری قوم — اپنی جگہ — پر عمل — کرو — میں بھی — عمل کر رہا ہوں — عنقریب — تم جانو گے — کس — پر عذاب — آتا ہے — اور کون — جھوٹا ہے — انتظار کرو — میں بھی — تمہارے ساتھ — انتظار — کرنے والا — ہوں۔
۳۔ عملی سبق: حق — پر — قائم رہو؛ انجام — خود — بولے گا۔"""
),
1567: (
"اور — جب — ہمارا حکم — آیا — ہم — نے — شعیبؑ — کو — اور — اس — کے ساتھ ایمان لانے والوں — کو — اپنی رحمت — سے نجات — دی — اور — ان — لوگوں کو — جنہوں نے ظلم — کیا — چیخ — نے پکڑ لیا — اور — وہ — اپنے گھروں — میں اوندھے — پڑے رہ — گئے",
"""۱۔ شعیبؑ اور مؤمنین — نجات؛ ظالموں کو — چیخ کا عذاب۔
۲۔ ’’وَلَمَّا جَاءَ أَمْرُنَا نَجَّيْنَا شُعَيْبًا وَالَّذِينَ آمَنُوا مَعَهُ بِرَحْمَۃٍ مِّنَّا وَأَخَذَتِ الَّذِينَ ظَلَمُوا الصَّيْحَۃُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ‘‘ — اور — جب — ہمارا حکم — آیا — ہم — نے — شعیبؑ — کو — اور — اس — کے ساتھ ایمان لانے والوں — کو — اپنی رحمت — سے نجات — دی — اور — ان — لوگوں کو — جنہوں نے ظلم — کیا — چیخ — نے پکڑ لیا — اور — وہ — اپنے گھروں — میں اوندھے — پڑے رہ — گئے — یعنی جب ہمارا حکم آیا — ہم نے شعیبؑ — اور — ان کے ساتھ — ایمان لانے والوں کو — اپنی رحمت سے — نجات — دی؛ اور ظالموں کو — چیخ — نے پکڑ لیا — اور — وہ — اپنے گھروں میں — اوندھے پڑے رہ — گئے۔
۳۔ عملی سبق: ایمان — اللہ کی حفاظت — میں ہے؛ ظلم — خود کو تباہ — کرتا ہے۔"""
),
1568: (
"گویا — وہ — وہاں — آباد ہی نہ تھے — سنو — مدین — کے لیے — ہلاکت — ہو گئی — جیسے ثمود — کا — خاتمہ ہوا",
"""۱۔ مدین — تباہ — ہو گیا — جیسے ثمود۔
۲۔ ’’كَأَن لَّمْ يَغْنَوْا فِيهَا أَلَا بُعْدًا لِّمَدْيَنَ كَمَا بَعِدَتْ ثَمُودُ‘‘ — گویا — وہ — وہاں — آباد ہی نہ تھے — سنو — مدین — کے لیے — ہلاکت — ہو گئی — جیسے ثمود — کا — خاتمہ ہوا — یعنی گویا — وہ — وہاں — کبھی آباد ہی نہیں تھے — سنو — مدین — کے لیے ہلاکت ہے — جیسے ثمود — کا خاتمہ ہوا۔
۳۔ عملی سبق: ظالموں کی تباہی — عبرت — ہے۔"""
),
1569: (
"اور — ہم — نے — موسیٰؑ — کو — اپنی آیات — کے ساتھ — بھیجا — اور — کھلی — دلیل — کے ساتھ",
"""۱۔ موسیٰؑ — کو — آیات اور کھلی دلیل — کے ساتھ بھیجا گیا۔
۲۔ ’’وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِآيَاتِنَا وَسُلْطَانٍ مُّبِينٍ‘‘ — اور — ہم — نے — موسیٰؑ — کو — اپنی آیات — کے ساتھ — بھیجا — اور — کھلی — دلیل — کے ساتھ — یعنی ہم نے — موسیٰؑ کو — اپنی آیات — اور کھلی دلیل — کے ساتھ بھیجا۔
۳۔ عملی سبق: پیغمبروں کے — ساتھ — همیشه — کھلی — دلیلیں — ہوتی ہیں۔"""
),
1570: (
"فرعون اور اس کے سردار — کی طرف — پس — انہوں نے — فرعون — کا حکم — اتباع کیا — اور — فرعون — کا حکم — درست — نہیں تھا",
"""۱۔ فرعون کی اطاعت — قوم — کا — زوال — ہے۔
۲۔ ’’إِلَىٰ فِرْعَوْنَ وَمَلَئِهِ فَاتَّبَعُوا أَمْرَ فِرْعَوْنَ وَمَا أَمْرُ فِرْعَوْنَ بِرَشِيدٍ‘‘ — فرعون اور اس کے سردار — کی طرف — پس — انہوں نے — فرعون — کا حکم — اتباع کیا — اور — فرعون — کا حکم — درست — نہیں تھا — یعنی فرعون اور اس کے سردار — کی طرف — موسیٰؑ کو بھیجا گیا — پس انہوں نے فرعون — کے حکم — کی پیروی — کی — اور — فرعون — کا حکم — درست — نہیں تھا۔
۳۔ عملی سبق: گمراہ — رہنما — کی پیروی — گمراہی — کا سبب ہے۔"""
),
1571: (
"وہ — قیامت کے دن — اپنی قوم — کے — آگے — چلے گا — پس — وہ — انہیں — آگ — میں — لے آئے گا — اور — وہ — برا — گھاٹ — ہے — جہاں — وہ — لے جائے گئے",
"""۱۔ فرعون — قیامت میں — اپنی قوم — کو — آگ — میں — ۔
۲۔ ’’يَقْدُمُ قَوْمَهُ يَوْمَ الْقِيَامَۃِ فَأَوْرَدَهُمُ النَّارَ وَبِئْسَ الْوِرْدُ الْمَوْرُودُ‘‘ — وہ — اپنی — قوم — کی آگے — قیامت کے دن — چلے گا — پس — انہیں — آگ — میں پا دیا — اور — وہ — برا — گھاٹ — ٹھکانہ — ہے — یعنی فرعون — قیامت کے دن — اپنی قوم — کا امام بن کر چلے گا — پس وہ — ان — کو — آگ — میں — لے جائے گا — اور — وہ — برا — گھاٹ — ہے — جہاں — انہیں — لے جایا گیا۔
۳۔ عملی سبق: اپنے — لیڈر — کا — انجام — دیکھ کر — سب — عبرت — لیں۔"""
),
1572: (
"اور — ان — کے پیچھے — اس — میں — لعنت — چلائی گئی — اور — قیامت کے دن — بھی — یہ — برا — تحفہ — ہے — جو — دیا گیا",
"""۱۔ فرعون اور قوم — پر — دنیا و آخرت — میں لعنت۔
۲۔ ’’وَأُتْبِعُوا فِي هَٰذِهِ لَعْنَۃً وَيَوْمَ الْقِيَامَۃِ بِئْسَ الرِّفْدُ الْمَرْفُودُ‘‘ — اور — ان — کے پیچھے — اس — میں — لعنت — چلائی گئی — اور — قیامت کے دن — بھی — یہ — برا — تحفہ — ہے — جو — دیا گیا — یعنی ان — کے پیچھے — اس دنیا میں لعنت — چلائی گئی — اور قیامت کے دن — بھی — یہ — برا تحفہ — ہے — جو — دیا گیا۔
۳۔ عملی سبق: لعنت — کافروں — کا — مقدر — ہے؛ بچنا — چاہیے۔"""
),
1573: (
"یہ — بستیوں — کی خبریں — ہیں — جن — کو — ہم — آپؐ — کو — سناتے ہیں — ان میں — کچھ — قائم ہیں — اور کچھ — کٹے — ہوئے ہیں",
"""۱۔ گزشتہ بستیوں — کی خبریں — نبیؐ — کے لیے — عبرت۔
۲۔ ’’ذَٰلِكَ مِنْ أَنبَاءِ الْقُرَىٰ نَقُصُّهُ عَلَيْكَ مِنْهَا قَائِمٌ وَحَصِيدٌ‘‘ — یہ — بستیوں — کی خبریں — ہیں — جن — کو — ہم — آپؐ — کو — سناتے ہیں — ان میں — کچھ — قائم ہیں — اور کچھ — کٹے — ہوئے ہیں — یعنی یہ — بستیوں کی خبریں — ہیں — جو ہم آپؐ کو سنا رہے ہیں — ان میں سے — کچھ — قائم ہیں — اور کچھ — کٹے ہوئے — ہیں۔
۳۔ عملی سبق: ماضی — کے — عبرت — نامہ — سے — سبق — حاصل کرو۔"""
),
}
